/* ── NUBES ── */
const cloudsEl = document.getElementById('clouds');
[
  { w:170, h:48, top:'7%',  delay:0,  dur:30 },
  { w:230, h:58, top:'13%', delay:9,  dur:38 },
  { w:140, h:38, top:'4%',  delay:18, dur:24 },
  { w:200, h:52, top:'19%', delay:5,  dur:34 },
].forEach(c => {
  const el = document.createElement('div');
  el.className = 'cloud';
  Object.assign(el.style, { width:c.w+'px', height:c.h+'px', top:c.top, animationDelay:c.delay+'s', animationDuration:c.dur+'s' });
  [[1.1,.55,.25],[.8,.3,.55]].forEach(([ws,ts,ls]) => {
    const b = document.createElement('div');
    const sz = c.h*ws;
    b.style.cssText = `position:absolute;width:${sz}px;height:${sz}px;top:-${c.h*ts}px;left:${c.w*ls}px;background:#ffffffd0;border-radius:50%`;
    el.appendChild(b);
  });
  cloudsEl.appendChild(el);
});

/* ── DIBUJA GIRASOL EN CANVAS ── */
function drawSunflower(canvas, size) {
  const ctx = canvas.getContext('2d');
  const cx = size / 2, cy = size / 2;
  const petalCount = 20;
  const petalLen   = size * 0.37;
  const petalW     = size * 0.12;
  const coreR      = size * 0.24;

  ctx.clearRect(0, 0, size, size);

  /* pétalos traseros */
  for (let i = 0; i < petalCount; i++) {
    const angle = (Math.PI * 2 / petalCount) * i + Math.PI / petalCount;
    ctx.save();
    ctx.translate(cx, cy);
    ctx.rotate(angle);
    const g = ctx.createRadialGradient(0, -petalLen*.35, 0, 0, -petalLen*.5, petalLen);
    g.addColorStop(0, '#d47d00');
    g.addColorStop(1, '#994500');
    ctx.fillStyle = g;
    ctx.beginPath();
    ctx.ellipse(0, -(coreR*.58 + petalLen*.44), petalW*.52, petalLen*.47, 0, 0, Math.PI*2);
    ctx.fill();
    ctx.restore();
  }

  /* pétalos delanteros */
  for (let i = 0; i < petalCount; i++) {
    const angle = (Math.PI * 2 / petalCount) * i;
    ctx.save();
    ctx.translate(cx, cy);
    ctx.rotate(angle);
    const g = ctx.createRadialGradient(0, -petalLen*.2, petalW*.1, 0, -petalLen*.6, petalLen);
    g.addColorStop(0,   '#FFE800');
    g.addColorStop(0.5, '#FFD000');
    g.addColorStop(1,   '#FFA000');
    ctx.fillStyle = g;
    ctx.beginPath();
    ctx.ellipse(0, -(coreR*.7 + petalLen*.48), petalW*.5, petalLen*.52, 0, 0, Math.PI*2);
    ctx.fill();
    /* nervio */
    ctx.strokeStyle = 'rgba(180,100,0,0.25)';
    ctx.lineWidth = 1.5;
    ctx.beginPath();
    ctx.moveTo(0, -coreR*.68);
    ctx.lineTo(0, -(coreR*.7 + petalLen*.9));
    ctx.stroke();
    ctx.restore();
  }

  /* centro */
  const cg = ctx.createRadialGradient(cx-coreR*.18, cy-coreR*.18, coreR*.04, cx, cy, coreR);
  cg.addColorStop(0,   '#7a3b10');
  cg.addColorStop(0.5, '#5c2a0a');
  cg.addColorStop(1,   '#3b1a06');
  ctx.beginPath();
  ctx.arc(cx, cy, coreR, 0, Math.PI*2);
  ctx.fillStyle = cg;
  ctx.fill();

  /* semillas en espiral Fibonacci */
  const phi = (1 + Math.sqrt(5)) / 2;
  for (let n = 0; n < 220; n++) {
    const r  = Math.sqrt(n / 220) * coreR * .88;
    const th = n * 2 * Math.PI / (phi * phi);
    const sx = cx + r * Math.cos(th);
    const sy = cy + r * Math.sin(th);
    const sr = coreR * .052 * (1 - r / coreR * .35);
    ctx.beginPath();
    ctx.arc(sx, sy, sr, 0, Math.PI*2);
    ctx.fillStyle = n % 3 === 0 ? '#7a4520' : '#4a2008';
    ctx.fill();
    ctx.beginPath();
    ctx.arc(sx - sr*.3, sy - sr*.3, sr*.36, 0, Math.PI*2);
    ctx.fillStyle = 'rgba(255,190,110,0.15)';
    ctx.fill();
  }

  /* brillo */
  const shine = ctx.createRadialGradient(cx-coreR*.3, cy-coreR*.3, 0, cx, cy, coreR*.72);
  shine.addColorStop(0, 'rgba(255,255,200,0.20)');
  shine.addColorStop(1, 'rgba(0,0,0,0)');
  ctx.beginPath();
  ctx.arc(cx, cy, coreR, 0, Math.PI*2);
  ctx.fillStyle = shine;
  ctx.fill();
}

/* ── CONSTRUYE GIRASOLES ── */
const garden = document.getElementById('garden');
const vh = window.innerHeight;

const defs = [
  { size: 155 },
  { size: 135 },
  { size: 180 },
  { size: 145 },
  { size: 195 },
  { size: 138 },
  { size: 172 },
  { size: 150 },
  { size: 165 },
];

defs.forEach((def, i) => {
  const size  = def.size + (Math.random() * 16 - 8);
  const stemH = Math.round(size * 0.55 + Math.random() * 20);
  const delay = i * 0.16;

  const wrap = document.createElement('div');
  wrap.className = 'flower-wrap';
  wrap.style.animationDelay = delay + 's';

  /* cabeza */
  const head = document.createElement('div');
  head.className = 'head';
  head.style.animationDelay = (Math.random()*2) + 's';

  const canvas = document.createElement('canvas');
  canvas.className = 'sunflower-canvas';
  canvas.width = canvas.height = Math.round(size);
  drawSunflower(canvas, Math.round(size));
  head.appendChild(canvas);

  /* tallo */
  const stem = document.createElement('div');
  stem.className = 'stem';
  stem.style.height = stemH + 'px';

  /* hojas SVG inline en el tallo */
  const leafPos1 = Math.round(stemH * .36);
  const leafPos2 = Math.round(stemH * .60);
  stem.innerHTML = `
    <svg style="position:absolute;top:${leafPos1}px;left:-34px;overflow:visible" width="80" height="28" viewBox="0 0 80 28">
      <ellipse cx="20" cy="14" rx="32" ry="12" fill="url(#lg1)" transform="rotate(-28,20,14)"/>
      <defs><radialGradient id="lg1" cx="55%" cy="40%"><stop offset="0%" stop-color="#76c442"/><stop offset="100%" stop-color="#3a7a22"/></radialGradient></defs>
    </svg>
    <svg style="position:absolute;top:${leafPos2}px;left:6px;overflow:visible" width="80" height="28" viewBox="0 0 80 28">
      <ellipse cx="60" cy="14" rx="32" ry="12" fill="url(#lg2)" transform="rotate(28,60,14)"/>
      <defs><radialGradient id="lg2" cx="45%" cy="40%"><stop offset="0%" stop-color="#76c442"/><stop offset="100%" stop-color="#3a7a22"/></radialGradient></defs>
    </svg>
  `;

  wrap.appendChild(head);
  wrap.appendChild(stem);
  garden.appendChild(wrap);
});

