const PHOTOS = ["data:image/png;base64,", "data:image/png;base64,", "data:image/png;base64,"];

/* ── POLAROIDS QUE CAEN ── */
const polContainer = document.getElementById('polaroids');
const labels = ['💛', 'Ñatty 🌻', '💛🌻', 'para ti', '🌻💛'];

function spawnPolaroid() {
  const idx = Math.floor(Math.random() * PHOTOS.length);
  const rot = (Math.random() * 24 - 12).toFixed(1);
  const left = (10 + Math.random() * 75).toFixed(1);
  const dur  = (5 + Math.random() * 4).toFixed(1);

  const pol = document.createElement('div');
  pol.className = 'polaroid';
  pol.style.cssText = `left:${left}%;top:-220px;--rot:${rot}deg;animation-duration:${dur}s`;

  const img = document.createElement('img');
  img.src = PHOTOS[idx];
  const lbl = document.createElement('div');
  lbl.className = 'pol-label';
  lbl.textContent = labels[Math.floor(Math.random()*labels.length)];

  pol.appendChild(img);
  pol.appendChild(lbl);
  polContainer.appendChild(pol);

  setTimeout(() => pol.remove(), parseFloat(dur) * 1000 + 200);
}

// Lanza la primera a los 2s, luego cada 4-7s
setTimeout(() => {
  spawnPolaroid();
  setInterval(spawnPolaroid, 4500 + Math.random() * 2500);
}, 2000);
